insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (6637, 2, 'Mietpreisbremse auslaufen lassen, um Investitionen anzuregen', 'Soll Investitionen anregen; Neubauten sind von der Mietpreisbremse ohnehin ausgenommen, die Wirkung auf den Neubau ist daher gering. Studien finden keinen deutlichen Rückgang des Neubaus durch die Bremse.', 'gemischt', null, 'bund', null, true, null),
  (6638, 2, 'Bundesweiter Mietendeckel', 'Begrenzt Mieten direkt, auch bei Neuvermietung, schafft aber keine neuen Wohnungen; in Berlin sanken 2020/21 die regulierten Mieten, zugleich wurden weniger Wohnungen angeboten. Ob ein bundesweiter Deckel mit Absenkung verfassungsgemäß wäre, ist offen.', 'gemischt', null, 'bund', null, true, null),
  (6639, 2, 'Mietenstopp in angespannten Wohnungsmärkten', 'Stoppt Erhöhungen in laufenden Mietverträgen in angespannten Märkten; schafft keine neuen Wohnungen und kann Instandhaltung und Modernisierung bremsen. Ein Mietenstopp wirft verfassungsrechtliche Fragen auf.', 'gemischt', null, 'bund', null, true, null),
  (6640, 2, 'Bessere steuerliche Abschreibung für den Mietwohnungsbau', 'Steuerliche Anreize können Neubau anstoßen; kostet Steuereinnahmen, und ob die Wohnungen günstig vermietet werden, ist nicht gesichert. Frühere Sonderabschreibungen wirkten vor allem bei ohnehin geplanten Projekten.', 'gemischt', null, 'bund', null, true, null),
  (6641, 2, 'Keine neuen kostentreibenden Baustandards, einfachere Standards und digitale Verfahren', 'Verhindert weitere Kostensteigerungen durch Vorschriften und verkürzt Verfahren; bereits gestiegene Material-, Lohn- und Zinskosten bleiben. Wie viel Standards an den Baukosten ausmachen, ist umstritten.', 'gemischt', null, 'bund', null, true, null),
  (6642, 2, 'Sozialen und gemeinnützigen Wohnungsbau stärker fördern, mit langen Bindungen', 'Schafft preisgebundene Wohnungen für Haushalte mit geringem Einkommen; erfordert erhebliche öffentliche Mittel, der Umfang ist nicht beziffert.', 'belegt', null, 'bund', null, true, null),
  (6645, 2, 'Soziale Wohnraumförderung des Landes fortführen (ohne Ausbau)', 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'belegt', null, 'land', null, true, null),
  (6646, 2, 'Soziale Wohnraumförderung des Landes ausbauen, Bundesmittel voll kofinanzieren', 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'belegt', null, 'land', null, true, null),
  (6647, 2, 'Sozialbindung geförderter Wohnungen unbefristet', 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'gemischt', null, 'land', null, true, null),
  (6648, 2, 'Höhere Quote für Sozialwohnungen bei Neubauten (kooperative Baulandentwicklung)', 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'gemischt', null, 'land', null, true, null),
  (6649, 2, 'Fehlbelegungsabgabe für Mieter in Sozialwohnungen mit gestiegenem Einkommen', 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'gemischt', null, 'land', null, true, null),
  (6650, 2, 'Große Vermieter per Landesgesetz verpflichten, einen Teil der Wohnungen an WBS-Haushalte zu vermieten', 'Würde den Bestand an Wohnungen für Haushalte mit geringem Einkommen schnell erweitern; ob ein Land das regeln darf, ist fraglich, denn das Mietrecht ist Bundessache (Bundesverfassungsgericht 2021 zum Berliner Mietendeckel).', 'offen', null, 'land', null, true, null),
  (7232, 2, 'Kurzzeitvermietung und Zweckentfremdung begrenzen (Bund)', 'Weniger Ferienwohnungen und Leerstand bringen Wohnungen zurück auf den Mietmarkt, vor allem in Großstädten; bundesweit ist der Anteil klein. Zweckentfremdungsverbote erlassen die Länder, der Bund kann den Rahmen setzen.', 'gemischt', null, 'bund', null, true, null),
  (8722, 2, 'Landesprogramme für Neubau und Sicherung von Sozialwohnungen, Umfang nicht beziffert (Land)', 'Neue geförderte Wohnungen und gesicherte Bindungen wirken dem schrumpfenden Bestand direkt entgegen; der Umfang ist nicht beziffert, und bisher reichte die Förderung nicht, um auslaufende Bindungen auszugleichen.', 'belegt', 'https://www.bpb.de/kurz-knapp/zahlen-und-fakten/soziale-situation-in-deutschland/341826/sozialmietwohnungen/', 'land', null, true, 'blind'),
  (8723, 2, 'Längere Bindungsfristen für neu geförderte Sozialwohnungen, ohne feste Dauer (Land)', 'Längere Bindungen verhindern, dass neue Sozialwohnungen früh aus der Bindung fallen; die Dauer ist offen, viele Länder binden schon 25 bis 35 Jahre, die Wirkung zeigt sich erst in Jahrzehnten, und Bauherren nehmen Förderung womöglich seltener an.', 'gemischt', 'https://www.evangelisch.de/inhalte/243851/30-05-2025/kaum-neue-sozialwohnungen-immer-weniger-sozialwohnungen-deutschland', 'land', null, true, 'blind'),
  (8724, 2, 'Verbindliche Sozialquote bei großen Neubauprojekten beibehalten (Land)', 'Sichert weiterhin einen Anteil Sozialwohnungen in neuen Quartieren ohne volle Landesförderung; als Fortführung ändert sie nichts daran, dass mehr Wohnungen aus der Bindung fallen, und kleinere Bauvorhaben sind nicht erfasst.', 'gemischt', null, 'land', null, true, 'blind')
